CREATE TRIGGER donation_slug_insert_trigger
  BEFORE INSERT ON public.donation
  FOR EACH ROW
  WHEN (((new.name IS NOT NULL) AND (new.slug IS NULL)))
  EXECUTE FUNCTION public.set_slug_from_name();

CREATE TRIGGER event_slug_insert_trigger
  BEFORE INSERT ON public.event
  FOR EACH ROW
  WHEN (((new.name IS NOT NULL) AND (new.slug IS NULL)))
